def rob(nums: List[int]) -> int:
    import itertools
    max_val = 0
    n = len(nums)
    for r in range(n + 1):
        for indices in itertools.combinations(range(n), r):
            valid = True
            for i in range(len(indices) - 1):
                if indices[i+1] == indices[i] + 1:
                    valid = False
                    break
            if valid:
                current_sum = sum(nums[i] for i in indices)
                if current_sum > max_val:
                    max_val = current_sum
    return max_val

